<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import type {FormInstance} from 'ant-design-vue';
import {message} from 'ant-design-vue';
import {submitForm,api,dateTime,matches,pagination,showError,useActions,type Row} from './api';import AppIcon from './AppIcon.vue';import PagePanel from './PagePanel.vue';
const rows=ref<Row[]>([]),loading=ref(false),error=ref(''),search=ref(''),status=ref('all'),createOpen=ref(false),formRef=ref<FormInstance>(),form=ref({label:'',validDays:7}),secret=ref(''),detail=ref<Row|null>(null),now=ref(Date.now());const {busy,perform}=useActions();let timer:ReturnType<typeof setInterval>|undefined;
function tokenStatus(row:Row){return row.revokedAt?'revoked':new Date(row.expiresAt).getTime()<=now.value?'expired':'active'}
const filtered=computed(()=>rows.value.filter(row=>matches(row,search.value,['label','id'])&&(status.value==='all'||tokenStatus(row)===status.value))),active=computed(()=>rows.value.filter(row=>tokenStatus(row)==='active').length),expired=computed(()=>rows.value.filter(row=>tokenStatus(row)==='expired').length);
async function refresh(){loading.value=true;error.value='';try{rows.value=await api('/api/agents');now.value=Date.now()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function openCreate(){form.value={label:'',validDays:7};createOpen.value=true}
async function create(){const result=await perform('/api/agents',form.value,'POST','Agent 凭据已创建');if(result){secret.value=result.token;createOpen.value=false;form.value={label:'',validDays:7};await refresh()}}
async function revoke(row:Row){if(await perform('/api/agents/'+row.id+'/revoke',{},'POST','凭据已撤销'))await refresh()}
async function copy(){try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(secret.value);else{const input=document.createElement('textarea');input.value=secret.value;input.style.position='fixed';input.style.opacity='0';document.body.append(input);input.select();const copied=document.execCommand('copy');input.remove();if(!copied)throw Error()}message.success('令牌已复制')}catch{showError(Error('复制失败，请选中令牌后手动复制'))}}
watch(createOpen,open=>{if(!open)formRef.value?.clearValidate()});onMounted(()=>{void refresh();timer=setInterval(()=>now.value=Date.now(),60000)});onBeforeUnmount(()=>{if(timer)clearInterval(timer);secret.value=''});defineExpose({refresh});
</script>
<template>
 <a-alert v-if="error" :message="error" type="error" show-icon class="dg-notice"/>
 <div class="dg-summary"><div><span>我的 Agent 凭据</span><strong>{{rows.length}}</strong></div><div><span>有效凭据</span><strong>{{active}}</strong></div><div><span>已过期</span><strong>{{expired}}</strong></div><div><span>已撤销</span><strong>{{rows.length-active-expired}}</strong></div></div>
 <PagePanel title="我的 Agent"><template #actions><a-button type="primary" @click="openCreate"><AppIcon name="plus"/>创建 Agent</a-button></template><template #filters><a-input v-model:value="search" allow-clear placeholder="搜索名称或凭据 ID" class="dg-search" aria-label="搜索 Agent"><template #prefix><AppIcon name="search"/></template></a-input><a-select v-model:value="status" class="dg-select" aria-label="凭据状态" :options="[{value:'all',label:'全部状态'},{value:'active',label:'有效'},{value:'expired',label:'已过期'},{value:'revoked',label:'已撤销'}]"/></template><a-table :data-source="filtered" :loading="loading" row-key="id" :pagination="pagination" :scroll="{x:800}"><a-table-column title="Agent" :width="260"><template #default="{record}"><div class="dg-name-cell"><span class="dg-resource-icon blue"><AppIcon name="agents"/></span><div><strong>{{record.label}}</strong><small>{{record.id.slice(0,8)}}</small></div></div></template></a-table-column><a-table-column title="创建时间"><template #default="{record}">{{dateTime(record.createdAt)}}</template></a-table-column><a-table-column title="到期时间"><template #default="{record}">{{dateTime(record.expiresAt)}}</template></a-table-column><a-table-column title="状态"><template #default="{record}"><span class="dg-status" :class="tokenStatus(record)==='active'?'good':'off'">{{tokenStatus(record)==='active'?'有效':tokenStatus(record)==='revoked'?'已撤销':'已过期'}}</span></template></a-table-column><a-table-column title="操作" align="right" :width="140"><template #default="{record}"><div class="dg-row-actions"><a-button type="link" @click="detail=record">详情</a-button><a-popconfirm v-if="!record.revokedAt" title="撤销后此令牌将无法访问，确认撤销？" ok-text="撤销" cancel-text="取消" @confirm="revoke(record)"><a-button type="link" danger :disabled="busy">撤销</a-button></a-popconfirm></div></template></a-table-column></a-table><template #footer>列表显示最近 100 个本人凭据</template></PagePanel>
 <a-modal v-model:open="createOpen" title="创建 Agent 凭据" centered :width="520" ok-text="创建" cancel-text="取消" :confirm-loading="busy" @ok="submitForm(formRef,create)"><a-form ref="formRef" :model="form" layout="vertical" @finish="create"><a-form-item label="名称" name="label" :rules="[{required:true,whitespace:true,message:'请输入 Agent 名称'},{max:100,message:'名称不能超过 100 个字符'}]"><a-input v-model:value="form.label" placeholder="Agent 名称" :maxlength="100"/></a-form-item><a-form-item label="有效天数" name="validDays" :rules="[{required:true,type:'number',min:1,max:90,message:'有效期为 1 到 90 天'}]"><a-input-number v-model:value="form.validDays" :min="1" :max="90" addon-after="天"/></a-form-item></a-form></a-modal>
 <a-modal :open="!!secret" title="保存访问令牌" centered :width="600" :footer="null" :mask-closable="false" @cancel="secret=''"><p class="dg-field-note">令牌仅展示一次，请妥善保存。</p><a-textarea :value="secret" readonly :rows="3" class="dg-secret" aria-label="新创建的访问令牌"/><div class="dg-modal-footer"><a-button @click="copy">复制令牌</a-button><a-button type="primary" @click="secret=''">已保存</a-button></div></a-modal>
 <a-modal :open="!!detail" title="Agent 凭据详情" centered :footer="null" @cancel="detail=null"><a-descriptions v-if="detail" :column="1" layout="vertical"><a-descriptions-item label="名称">{{detail.label}}</a-descriptions-item><a-descriptions-item label="凭据 ID">{{detail.id}}</a-descriptions-item><a-descriptions-item label="创建时间">{{dateTime(detail.createdAt)}}</a-descriptions-item><a-descriptions-item label="到期时间">{{dateTime(detail.expiresAt)}}</a-descriptions-item><a-descriptions-item label="撤销时间">{{dateTime(detail.revokedAt)}}</a-descriptions-item></a-descriptions><div class="dg-modal-footer"><a-button @click="detail=null">关闭</a-button></div></a-modal>
</template>
